begin;
create table if not exists public.sasi_continuity_projects(project_id uuid primary key default gen_random_uuid(),owner_id uuid not null,kind text not null,goal text not null default '',dna jsonb not null default '{}'::jsonb,revision bigint not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.sasi_continuity_results(result_id uuid primary key default gen_random_uuid(),project_id uuid not null references public.sasi_continuity_projects(project_id) on delete cascade,owner_id uuid not null,intent text not null,capability_path jsonb not null default '[]'::jsonb,accepted boolean not null default false,validation_score numeric not null default 0 check(validation_score>=0 and validation_score<=1),repairs jsonb not null default '[]'::jsonb,metrics jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.sasi_failure_atlas(fingerprint text primary key,capability text not null,code text not null,provider text,context jsonb not null default '{}'::jsonb,occurrences bigint not null default 1 check(occurrences>0),successful_repairs jsonb not null default '{}'::jsonb,last_seen timestamptz not null default now());
alter table public.sasi_continuity_projects enable row level security;alter table public.sasi_continuity_results enable row level security;alter table public.sasi_failure_atlas enable row level security;
drop policy if exists sasi_continuity_projects_owner on public.sasi_continuity_projects;create policy sasi_continuity_projects_owner on public.sasi_continuity_projects for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
drop policy if exists sasi_continuity_results_owner on public.sasi_continuity_results;create policy sasi_continuity_results_owner on public.sasi_continuity_results for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
commit;
